IF OBJECT_ID('dbo.exp_invoices') IS NULL
CREATE TABLE dbo.[exp_invoices] (
  [id] BIGINT IDENTITY(1,1) NOT NULL,
  [inv_no] NVARCHAR(450) NULL,
  [inv_year] INT NULL,
  [inv_seq] INT NULL,
  [inv_date] DATE NOT NULL CONSTRAINT [df_exp_invoices_inv_date] DEFAULT CAST(SYSUTCDATETIME() AS DATE),
  [vendor_id] BIGINT NULL,
  [vendor] NVARCHAR(MAX) NULL CONSTRAINT [ck_exp_invoices_vendor_json] CHECK ([vendor] IS NULL OR ISJSON([vendor]) = 1),
  [category] NVARCHAR(MAX) NULL,
  [ref_no] NVARCHAR(MAX) NULL,
  [ref_date] DATE NULL,
  [po_no] NVARCHAR(MAX) NULL,
  [wht_rate] DECIMAL(19,4) NOT NULL CONSTRAINT [df_exp_invoices_wht_rate] DEFAULT 0,
  [amount] DECIMAL(19,4) NOT NULL CONSTRAINT [df_exp_invoices_amount] DEFAULT 0,
  [vat] DECIMAL(19,4) NOT NULL CONSTRAINT [df_exp_invoices_vat] DEFAULT 0,
  [wht] DECIMAL(19,4) NOT NULL CONSTRAINT [df_exp_invoices_wht] DEFAULT 0,
  [net] DECIMAL(19,4) NOT NULL CONSTRAINT [df_exp_invoices_net] DEFAULT 0,
  [status] NVARCHAR(450) NOT NULL CONSTRAINT [df_exp_invoices_status] DEFAULT N'draft',
  [note] NVARCHAR(MAX) NULL,
  [reject_reason] NVARCHAR(MAX) NULL,
  [reviewer_id] UNIQUEIDENTIFIER NULL,
  [approver_id] UNIQUEIDENTIFIER NULL,
  [preparer] NVARCHAR(MAX) NULL CONSTRAINT [ck_exp_invoices_preparer_json] CHECK ([preparer] IS NULL OR ISJSON([preparer]) = 1),
  [reviewer] NVARCHAR(MAX) NULL CONSTRAINT [ck_exp_invoices_reviewer_json] CHECK ([reviewer] IS NULL OR ISJSON([reviewer]) = 1),
  [approver] NVARCHAR(MAX) NULL CONSTRAINT [ck_exp_invoices_approver_json] CHECK ([approver] IS NULL OR ISJSON([approver]) = 1),
  [prepared_by] UNIQUEIDENTIFIER NULL,
  [submitted_at] DATETIMEOFFSET NULL,
  [reviewed_by] UNIQUEIDENTIFIER NULL,
  [reviewed_at] DATETIMEOFFSET NULL,
  [approved_by] UNIQUEIDENTIFIER NULL,
  [approved_at] DATETIMEOFFSET NULL,
  [received_name] NVARCHAR(MAX) NULL,
  [received_at] DATE NULL,
  [imported] BIT NOT NULL CONSTRAINT [df_exp_invoices_imported] DEFAULT 0,
  [created_by] UNIQUEIDENTIFIER NULL,
  [created_at] DATETIMEOFFSET NULL CONSTRAINT [df_exp_invoices_created_at] DEFAULT SYSDATETIMEOFFSET(),
  [updated_at] DATETIMEOFFSET NULL CONSTRAINT [df_exp_invoices_updated_at] DEFAULT SYSDATETIMEOFFSET(),
  CONSTRAINT [pk_exp_invoices] PRIMARY KEY ([id]),
  CONSTRAINT [ck_exp_invoices_0] CHECK (([status] IN (N'draft', N'review', N'approval', N'approved', N'received', N'rejected', N'cancelled'))),
  CONSTRAINT [ck_exp_invoices_1] CHECK (([wht_rate] IN (0, 1, 2, 3, 5)))
);

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'uq_exp_invoices_inv_no_key')
CREATE UNIQUE INDEX [uq_exp_invoices_inv_no_key] ON dbo.[exp_invoices] ([inv_no]) WHERE [inv_no] IS NOT NULL;

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'uq_exp_invoices_inv_year_inv_seq_key')
