IF OBJECT_ID('dbo.fund_form_invite') IS NULL
CREATE TABLE dbo.[fund_form_invite] (
  [id] BIGINT IDENTITY(1,1) NOT NULL,
  [token] NVARCHAR(450) NOT NULL CONSTRAINT [df_fund_form_invite_token] DEFAULT REPLACE(LOWER(CONVERT(NVARCHAR(36), NEWID())), N'-', N''),
  [emp_code] NVARCHAR(450) NOT NULL,
  [title] NVARCHAR(MAX) NULL,
  [emp_name] NVARCHAR(MAX) NULL,
  [department] NVARCHAR(MAX) NULL,
  [id_last5] NVARCHAR(MAX) NOT NULL,
  [forms] NVARCHAR(MAX) NOT NULL CONSTRAINT [ck_fund_form_invite_forms_json] CHECK ([forms] IS NULL OR ISJSON([forms]) = 1),
  [expires_at] DATETIMEOFFSET NOT NULL CONSTRAINT [df_fund_form_invite_expires_at] DEFAULT DATEADD(day, 30, SYSDATETIMEOFFSET()),
  [cancelled] BIT NOT NULL CONSTRAINT [df_fund_form_invite_cancelled] DEFAULT 0,
  [opened_at] DATETIMEOFFSET NULL,
  [created_at] DATETIMEOFFSET NOT NULL CONSTRAINT [df_fund_form_invite_created_at] DEFAULT SYSDATETIMEOFFSET(),
  [created_by] UNIQUEIDENTIFIER NULL,
  CONSTRAINT [pk_fund_form_invite] PRIMARY KEY ([id]),
  CONSTRAINT [ck_fund_form_invite_0] CHECK (ISJSON([forms]) = 1 AND [forms] <> N'[]' AND REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE([forms], N'"pvd"', N''), N'"wef"', N''), N',', N''), N' ', N''), N'[', N''), N']', N'') = N''),
  CONSTRAINT [ck_fund_form_invite_1] CHECK ((LEN([id_last5]) = 5 AND [id_last5] NOT LIKE N'%[^0-9]%'))
);

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'uq_fund_form_invite_token_key')
CREATE UNIQUE INDEX [uq_fund_form_invite_token_key] ON dbo.[fund_form_invite] ([token]);

