IF OBJECT_ID('dbo.ot_shift_times') IS NULL
CREATE TABLE dbo.[ot_shift_times] (
  [code] NVARCHAR(450) NOT NULL,
  [start_min] INT NOT NULL,
  [end_min] INT NOT NULL,
  [break_start] INT NULL,
  [break_end] INT NULL,
  [note] NVARCHAR(MAX) NULL,
  [updated_by] NVARCHAR(MAX) NULL,
  [updated_at] DATETIMEOFFSET NULL CONSTRAINT [df_ot_shift_times_updated_at] DEFAULT SYSDATETIMEOFFSET(),
  [by_hours] BIT NOT NULL CONSTRAINT [df_ot_shift_times_by_hours] DEFAULT 0,
  [hours_span] INT NULL,
  CONSTRAINT [pk_ot_shift_times] PRIMARY KEY ([code]),
  CONSTRAINT [ck_ot_shift_times_0] CHECK ((([end_min] > [start_min]) AND ([end_min] <= ([start_min] + 1440)))),
  CONSTRAINT [ck_ot_shift_times_1] CHECK (([break_start] IS NULL AND [break_end] IS NULL) OR ([break_start] IS NOT NULL AND [break_end] IS NOT NULL)),
  CONSTRAINT [ck_ot_shift_times_2] CHECK ((([break_start] IS NULL) OR (([break_end] > [break_start]) AND ([break_start] >= [start_min]) AND ([break_end] <= [end_min])))),
  CONSTRAINT [ck_ot_shift_times_3] CHECK ((([hours_span] IS NULL) OR ([hours_span] IN (510, 570)))),
  CONSTRAINT [ck_ot_shift_times_4] CHECK ((([start_min] >= 0) AND ([start_min] <= 1439)))
);

