  [created_at] DATETIMEOFFSET NULL CONSTRAINT [df_uniform_move_created_at] DEFAULT SYSDATETIMEOFFSET(),
  [created_by] UNIQUEIDENTIFIER NULL,
  CONSTRAINT [pk_uniform_move] PRIMARY KEY ([id]),
  CONSTRAINT [ck_uniform_move_0] CHECK (((([move_type] IN (N'receive', N'return')) AND ([qty] > 0)) OR (([move_type] = N'issue') AND ([qty] < 0)) OR ([move_type] = N'adjust'))),
  CONSTRAINT [ck_uniform_move_1] CHECK ((([move_type] <> N'issue') OR ([emp_code] IS NOT NULL))),
  CONSTRAINT [ck_uniform_move_2] CHECK (([move_type] IN (N'receive', N'issue', N'return', N'adjust'))),
  CONSTRAINT [ck_uniform_move_3] CHECK (([qty] <> 0))
);

